tools.example:
model.study().create("std1");
model.study("std1").create("mode", "ModeAnalysis");
model.study("std1").feature("mode").set("modeFreq", "c_const/1550[nm]");
model.study("std1").feature("mode").set("neigs", 4);
model.study("std1").feature("mode").set("shift", "1.45");
// results: emw.neff, emw.beta, emw.dampz

// boundary condition: V0 = V_dc + linper(V_ac)
model.study().create("std1");
model.study("std1").create("stat", "Stationary");
// then add the Frequency-Domain Perturbation step from the GUI (Study > Study Steps > Frequency Domain > Frequency-Domain Perturbation)
// results: lindev(es.V), abs(lintotal(...))

model.study().create("std1");
model.study("std1").create("stat", "Stationary");
model.study("std1").feature("stat").set("geometricNonlinearity", true);
model.study("std1").create("eig", "Eigenfrequency");
model.study("std1").feature("eig").set("geometricNonlinearity", true);
model.study("std1").feature("eig").set("neigs", 10);
model.sol().createAutoSequence("std1");

model.study().create("std1");
model.study("std1").create("stat", "Stationary");
model.study("std1").create("buckling", "LinearBuckling");
model.study("std1").feature("buckling").set("neigs", 4);
model.sol().createAutoSequence("std1");
model.study("std1").run();
// Results > Global Evaluation: lambda

model.study().create("std1");
model.study("std1").create("ssw", "StationarySourceSweep");
model.sol().createAutoSequence("std1");
model.study("std1").run();
// Results > Derived Values > Global Matrix Evaluation: es.C

model.study("std1").feature("stat").set("sensitivity", true);
model.study("std1").feature("stat").set("sensmethod", "adjoint");
model.study("std1").feature("stat").set("objectives", new String[]{"intop1(T)"});
model.study("std1").feature("stat").set("sensparams", new String[]{"k_ins", "h_conv"});
// Results: fsens(k_ins)

model.study().create("std2");
model.study("std2").create("mr", "ModelReduction");
model.study("std2").feature("mr").set("trainingStudy", "std1");
model.study("std2").feature("mr").set("unreducedModelStudy", "std1");
model.study("std2").run();
// Global Definitions > Reduced-Order Model rom1: export state-space matrices

model.study("std1").create("stat", "Stationary");
model.study("std1").feature("stat").activate("spf", true);
model.study("std1").feature("stat").activate("ht", false);
model.study("std1").create("stat2", "Stationary");
model.study("std1").feature("stat2").activate("spf", false);
model.study("std1").feature("stat2").activate("ht", true);

model.loadGroup().create("lg1");
model.loadGroup().create("lg2");
model.component("comp1").physics("solid").feature("bndl1").set("loadGroup", "lg1");
model.component("comp1").physics("solid").feature("bndl2").set("loadGroup", "lg2");
model.study("std1").feature("stat").set("useloadcase", "on");
model.study("std1").feature("stat").set("loadcase", new String[][]{{"Case A", "1", "0"}, {"Case B", "1", "1.5"}});

model.study("std1").feature("stat").set("adaption", "on");
model.study("std1").feature("stat").set("adaptmesh", "mesh1");
model.study("std1").feature("stat").set("maxadapt", 3);
model.study("std1").feature("stat").set("errorest", "l2");
model.study("std1").run();
// adapted meshes appear as Mesh 2, Mesh 3 ... with a Reference mesh node

model.sol("sol1").feature("s1").create("p1", "Parametric");
model.sol("sol1").feature("s1").feature("p1").set("pname", new String[]{"Vapp"});
model.sol("sol1").feature("s1").feature("p1").set("plistarr", new String[]{"range(0,5,100)"});
model.sol("sol1").feature("s1").feature("p1").set("punit", new String[]{"V"});
model.sol("sol1").feature("s1").feature("p1").set("pcontinuationmode", "auto");
model.sol("sol1").feature("s1").feature("p1").set("porder", "linear");

model.sol("sol1").feature("t1").set("timemethod", "genalpha");
model.sol("sol1").feature("t1").set("rhoinf", 0.75);
// or BDF limited to second order
model.sol("sol1").feature("t1").set("timemethod", "bdf");
model.sol("sol1").feature("t1").set("maxorder", 2);

// command line: comsol batch -inputfile m.mph -outputfile o.mph -batchlog run.log
// Java: enable progress/log output to the console
ModelUtil.showProgress(true);
model.sol("sol1").runAll();
